from typing import Final

import pytest

WIDTH: Final = 8
MASK: Final = 0xFF


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits (0 <= k <= 7).

    Bits shifted out of the high end wrap around to the low end.
    The result is always within 0..255.
    """
    x &= MASK
    return ((x << k) | (x >> (WIDTH - k))) & MASK


@pytest.mark.parametrize(
    ("x", "k", "expected"),
    [
        (0b10000001, 1, 0b00000011),
        (0x01, 0, 0x01),
        (0xFF, 3, 0xFF),
        (0x12, 4, 0x21),
        (0x80, 7, 0x40),
        (0x01, 7, 0x80),
        (0xA5, 0, 0xA5),
    ],
)
def test_rotl8(x: int, k: int, expected: int) -> None:
    assert rotl8(x, k) == expected


def test_rotl8_result_in_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= MASK


def test_rotl8_full_rotation_is_identity() -> None:
    for x in range(256):
        assert rotl8(x, 0) == x
